68	/*
69	 * Extend a string.
70	 */
71	
72	YAML_DECLARE(int)
73	yaml_string_extend(yaml_char_t **start,
74	        yaml_char_t **pointer, yaml_char_t **end)
75	{
76	    yaml_char_t *new_start = (yaml_char_t *)yaml_realloc((void*)*start, (*end - *start)*2);
77	
78	    if (!new_start) return 0;
79	
80	    memset(new_start + (*end - *start), 0, *end - *start);
81	
82	    *pointer = new_start + (*pointer - *start);
83	    *end = new_start + (*end - *start)*2;
84	    *start = new_start;
85	
86	    return 1;
87	}
