89	/*
90	 * Append a string B to a string A.
91	 */
92	
93	YAML_DECLARE(int)
94	yaml_string_join(
95	        yaml_char_t **a_start, yaml_char_t **a_pointer, yaml_char_t **a_end,
96	        yaml_char_t **b_start, yaml_char_t **b_pointer, SHIM(yaml_char_t **b_end))
97	{
98	    UNUSED_PARAM(b_end)
99	    if (*b_start == *b_pointer)
100	        return 1;
101	
102	    while (*a_end - *a_pointer <= *b_pointer - *b_start) {
103	        if (!yaml_string_extend(a_start, a_pointer, a_end))
104	            return 0;
105	    }
106	
107	    memcpy(*a_pointer, *b_start, *b_pointer - *b_start);
108	    *a_pointer += *b_pointer - *b_start;
109	
110	    return 1;
111	}
