43	/*
44	 * Peek the next token in the token queue.
45	 */
46	
47	#define PEEK_TOKEN(parser)                                                      \
48	    ((parser->token_available || yaml_parser_fetch_more_tokens(parser)) ?       \
49	        parser->tokens.head : NULL)
50	
51	/*
52	 * Remove the next token from the queue (must be called after PEEK_TOKEN).
53	 */
54	
55	#define SKIP_TOKEN(parser)                                                      \
56	    (parser->token_available = 0,                                               \
57	     parser->tokens_parsed ++,                                                  \
58	     parser->stream_end_produced =                                              \
59	        (parser->tokens.head->type == YAML_STREAM_END_TOKEN),                   \
60	     parser->tokens.head ++)
