325	/*
326	 * Parse the production:
327	 * stream   ::= STREAM-START implicit_document? explicit_document* STREAM-END
328	 *              ************
329	 */
330	
331	static int
332	yaml_parser_parse_stream_start(yaml_parser_t *parser, yaml_event_t *event)
333	{
334	    yaml_token_t *token;
335	
336	    token = PEEK_TOKEN(parser);
337	    if (!token) return 0;
338	
339	    if (token->type != YAML_STREAM_START_TOKEN) {
340	        return yaml_parser_set_parser_error(parser,
341	                "did not find expected <stream-start>", token->start_mark);
342	    }
343	
344	    parser->state = YAML_PARSE_IMPLICIT_DOCUMENT_START_STATE;
345	    STREAM_START_EVENT_INIT(*event, token->data.stream_start.encoding,
346	            token->start_mark, token->start_mark);
347	    SKIP_TOKEN(parser);
348	
349	    return 1;
350	}
351	
352	/*
353	 * Parse the productions:
354	 * implicit_document    ::= block_node DOCUMENT-END*
355	 *                          *
356	 * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
357	 *                          *************************
358	 */
359	
360	static int
361	yaml_parser_parse_document_start(yaml_parser_t *parser, yaml_event_t *event,
362	        int implicit)
363	{
364	    yaml_token_t *token;
365	    yaml_version_directive_t *version_directive = NULL;
366	    struct {
367	        yaml_tag_directive_t *start;
368	        yaml_tag_directive_t *end;
369	    } tag_directives = { NULL, NULL };
370	
371	    token = PEEK_TOKEN(parser);
372	    if (!token) return 0;
373	
374	    /* Parse extra document end indicators. */
375	
376	    if (!implicit)
377	    {
378	        while (token->type == YAML_DOCUMENT_END_TOKEN) {
379	            SKIP_TOKEN(parser);
380	            token = PEEK_TOKEN(parser);
381	            if (!token) return 0;
382	        }
383	    }
384	
385	    /* Parse an implicit document. */
386	
387	    if (implicit && token->type != YAML_VERSION_DIRECTIVE_TOKEN &&
388	            token->type != YAML_TAG_DIRECTIVE_TOKEN &&
389	            token->type != YAML_DOCUMENT_START_TOKEN &&
390	            token->type != YAML_STREAM_END_TOKEN)
391	    {
392	        if (!yaml_parser_process_directives(parser, NULL, NULL, NULL))
393	            return 0;
394	        if (!PUSH(parser, parser->states, YAML_PARSE_DOCUMENT_END_STATE))
395	            return 0;
396	        parser->state = YAML_PARSE_BLOCK_NODE_STATE;
397	        DOCUMENT_START_EVENT_INIT(*event, NULL, NULL, NULL, 1,
398	                token->start_mark, token->start_mark);
399	        return 1;
400	    }
401	
402	    /* Parse an explicit document. */
403	
404	    else if (token->type != YAML_STREAM_END_TOKEN)
405	    {
406	        yaml_mark_t start_mark, end_mark;
407	        start_mark = token->start_mark;
408	        if (!yaml_parser_process_directives(parser, &version_directive,
409	                    &tag_directives.start, &tag_directives.end))
410	            return 0;
411	        token = PEEK_TOKEN(parser);
412	        if (!token) goto error;
413	        if (token->type != YAML_DOCUMENT_START_TOKEN) {
414	            yaml_parser_set_parser_error(parser,
415	                    "did not find expected <document start>", token->start_mark);
416	            goto error;
417	        }
418	        if (!PUSH(parser, parser->states, YAML_PARSE_DOCUMENT_END_STATE))
419	            goto error;
420	        parser->state = YAML_PARSE_DOCUMENT_CONTENT_STATE;
421	        end_mark = token->end_mark;
422	        DOCUMENT_START_EVENT_INIT(*event, version_directive,
423	                tag_directives.start, tag_directives.end, 0,
424	                start_mark, end_mark);
425	        SKIP_TOKEN(parser);
426	        version_directive = NULL;
427	        tag_directives.start = tag_directives.end = NULL;
428	        return 1;
429	    }
430	
431	    /* Parse the stream end. */
432	
433	    else
434	    {
435	        parser->state = YAML_PARSE_END_STATE;
436	        STREAM_END_EVENT_INIT(*event, token->start_mark, token->end_mark);
437	        SKIP_TOKEN(parser);
438	        return 1;
439	    }
440	
441	error:
442	    yaml_free(version_directive);
443	    while (tag_directives.start != tag_directives.end) {
444	        yaml_free(tag_directives.end[-1].handle);
445	        yaml_free(tag_directives.end[-1].prefix);
446	        tag_directives.end --;
447	    }
448	    yaml_free(tag_directives.start);
449	    return 0;
450	}
451	
452	/*
453	 * Parse the productions:
454	 * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
455	 *                                                    ***********
456	 */
457	
458	static int
459	yaml_parser_parse_document_content(yaml_parser_t *parser, yaml_event_t *event)
460	{
461	    yaml_token_t *token;
462	
463	    token = PEEK_TOKEN(parser);
464	    if (!token) return 0;
465	
466	    if (token->type == YAML_VERSION_DIRECTIVE_TOKEN ||
467	            token->type == YAML_TAG_DIRECTIVE_TOKEN ||
468	            token->type == YAML_DOCUMENT_START_TOKEN ||
469	            token->type == YAML_DOCUMENT_END_TOKEN ||
470	            token->type == YAML_STREAM_END_TOKEN) {
471	        parser->state = POP(parser, parser->states);
472	        return yaml_parser_process_empty_scalar(parser, event,
473	                token->start_mark);
474	    }
475	    else {
476	        return yaml_parser_parse_node(parser, event, 1, 0);
477	    }
478	}
