1378	/*
1379	 * Append a tag directive to the directives stack.
1380	 */
1381	
1382	static int
1383	yaml_parser_append_tag_directive(yaml_parser_t *parser,
1384	        yaml_tag_directive_t value, int allow_duplicates, yaml_mark_t mark)
1385	{
1386	    yaml_tag_directive_t *tag_directive;
1387	    yaml_tag_directive_t copy = { NULL, NULL };
1388	
1389	    for (tag_directive = parser->tag_directives.start;
1390	            tag_directive != parser->tag_directives.top; tag_directive ++) {
1391	        if (strcmp((char *)value.handle, (char *)tag_directive->handle) == 0) {
1392	            if (allow_duplicates)
1393	                return 1;
1394	            return yaml_parser_set_parser_error(parser,
1395	                    "found duplicate %TAG directive", mark);
1396	        }
1397	    }
1398	
1399	    copy.handle = yaml_strdup(value.handle);
1400	    copy.prefix = yaml_strdup(value.prefix);
1401	    if (!copy.handle || !copy.prefix) {
1402	        parser->error = YAML_MEMORY_ERROR;
1403	        goto error;
1404	    }
1405	
1406	    if (!PUSH(parser, parser->tag_directives, copy))
1407	        goto error;
1408	
1409	    return 1;
1410	
1411	error:
1412	    yaml_free(copy.handle);
1413	    yaml_free(copy.prefix);
1414	    return 0;
1415	}
