2079	                    (octet & 0xE0) == 0xC0 ? octet & 0x1F :
2080	                    (octet & 0xF0) == 0xE0 ? octet & 0x0F :
2081	                    (octet & 0xF8) == 0xF0 ? octet & 0x07 : 0;
2082	            for (k = 1; k < (int)width; k ++) {
