2090	            switch (value)
2091	            {
2092	                case 0x00:
2093	                    if (!PUT(emitter, '0')) return 0;
2094	                    break;
2095	
2096	                case 0x07:
2097	                    if (!PUT(emitter, 'a')) return 0;
2098	                    break;
2099	
2100	                case 0x08:
2101	                    if (!PUT(emitter, 'b')) return 0;
2102	                    break;
2103	
2104	                case 0x09:
2105	                    if (!PUT(emitter, 't')) return 0;
2106	                    break;
