21	 * block_collection     ::= block_sequence | block_mapping
22	 * flow_collection      ::= flow_sequence | flow_mapping
23	 * block_sequence       ::= BLOCK-SEQUENCE-START (BLOCK-ENTRY block_node?)* BLOCK-END
24	 * indentless_sequence  ::= (BLOCK-ENTRY block_node?)+
25	 * block_mapping        ::= BLOCK-MAPPING_START
26	 *                          ((KEY block_node_or_indentless_sequence?)?
27	 *                          (VALUE block_node_or_indentless_sequence?)?)*
28	 *                          BLOCK-END
29	 * flow_sequence        ::= FLOW-SEQUENCE-START
30	 *                          (flow_sequence_entry FLOW-ENTRY)*
31	 *                          flow_sequence_entry?
32	 *                          FLOW-SEQUENCE-END
33	 * flow_sequence_entry  ::= flow_node | KEY flow_node? (VALUE flow_node?)?
34	 * flow_mapping         ::= FLOW-MAPPING-START
35	 *                          (flow_mapping_entry FLOW-ENTRY)*
36	 *                          flow_mapping_entry?
37	 *                          FLOW-MAPPING-END
38	 * flow_mapping_entry   ::= flow_node | KEY flow_node? (VALUE flow_node?)?
39	 */
40	
41	#include "yaml_private.h"
42	
43	/*
44	 * Peek the next token in the token queue.
45	 */
46	
47	#define PEEK_TOKEN(parser)                                                      \
48	    ((parser->token_available || yaml_parser_fetch_more_tokens(parser)) ?       \
49	        parser->tokens.head : NULL)
50	
51	/*
52	 * Remove the next token from the queue (must be called after PEEK_TOKEN).
53	 */
54	
55	#define SKIP_TOKEN(parser)                                                      \
56	    (parser->token_available = 0,                                               \
57	     parser->tokens_parsed ++,                                                  \
58	     parser->stream_end_produced =                                              \
59	        (parser->tokens.head->type == YAML_STREAM_END_TOKEN),                   \
60	     parser->tokens.head ++)
61	
62	/*
63	 * Public API declarations.
64	 */
65	
66	int MAX_NESTING_LEVEL = 1000;
67	
68	YAML_DECLARE(int)
69	yaml_parser_parse(yaml_parser_t *parser, yaml_event_t *event);
70	
71	/*
72	 * Error handling.
73	 */
74	
75	static int
76	yaml_parser_set_parser_error(yaml_parser_t *parser,
77	        const char *problem, yaml_mark_t problem_mark);
78	
79	static int
80	yaml_parser_set_parser_error_context(yaml_parser_t *parser,
81	        const char *context, yaml_mark_t context_mark,
82	        const char *problem, yaml_mark_t problem_mark);
83	
84	static int
85	yaml_maximum_level_reached(yaml_parser_t *parser,
86	        yaml_mark_t context_mark, yaml_mark_t problem_mark);
87	
88	/*
89	 * State functions.
90	 */
91	
92	static int
93	yaml_parser_state_machine(yaml_parser_t *parser, yaml_event_t *event);
94	
95	static int
96	yaml_parser_parse_stream_start(yaml_parser_t *parser, yaml_event_t *event);
97	
98	static int
99	yaml_parser_parse_document_start(yaml_parser_t *parser, yaml_event_t *event,
100	        int implicit);
101	
102	static int
103	yaml_parser_parse_document_content(yaml_parser_t *parser, yaml_event_t *event);
104	
105	static int
106	yaml_parser_parse_document_end(yaml_parser_t *parser, yaml_event_t *event);
107	
108	static int
109	yaml_parser_parse_node(yaml_parser_t *parser, yaml_event_t *event,
110	        int block, int indentless_sequence);
111	
112	static int
113	yaml_parser_parse_block_sequence_entry(yaml_parser_t *parser,
114	        yaml_event_t *event, int first);
115	
116	static int
117	yaml_parser_parse_indentless_sequence_entry(yaml_parser_t *parser,
118	        yaml_event_t *event);
119	
120	static int
121	yaml_parser_parse_block_mapping_key(yaml_parser_t *parser,
122	        yaml_event_t *event, int first);
123	
124	static int
125	yaml_parser_parse_block_mapping_value(yaml_parser_t *parser,
126	        yaml_event_t *event);
127	
128	static int
129	yaml_parser_parse_flow_sequence_entry(yaml_parser_t *parser,
130	        yaml_event_t *event, int first);
131	
132	static int
133	yaml_parser_parse_flow_sequence_entry_mapping_key(yaml_parser_t *parser,
134	        yaml_event_t *event);
135	
136	static int
137	yaml_parser_parse_flow_sequence_entry_mapping_value(yaml_parser_t *parser,
138	        yaml_event_t *event);
139	
140	static int
141	yaml_parser_parse_flow_sequence_entry_mapping_end(yaml_parser_t *parser,
142	        yaml_event_t *event);
143	
144	static int
145	yaml_parser_parse_flow_mapping_key(yaml_parser_t *parser,
146	        yaml_event_t *event, int first);
147	
148	static int
149	yaml_parser_parse_flow_mapping_value(yaml_parser_t *parser,
150	        yaml_event_t *event, int empty);
151	
152	/*
153	 * Utility functions.
154	 */
155	
156	static int
157	yaml_parser_process_empty_scalar(yaml_parser_t *parser,
158	        yaml_event_t *event, yaml_mark_t mark);
159	
160	static int
161	yaml_parser_process_directives(yaml_parser_t *parser,
162	        yaml_version_directive_t **version_directive_ref,
163	        yaml_tag_directive_t **tag_directives_start_ref,
164	        yaml_tag_directive_t **tag_directives_end_ref);
165	
166	static int
167	yaml_parser_append_tag_directive(yaml_parser_t *parser,
168	        yaml_tag_directive_t value, int allow_duplicates, yaml_mark_t mark);
169	
170	YAML_DECLARE(void)
171	yaml_set_max_nest_level(int max)
172	{
173	    MAX_NESTING_LEVEL = max;
174	}
175	
176	/*
177	 * Get the next event.
178	 */
179	
180	YAML_DECLARE(int)
181	yaml_parser_parse(yaml_parser_t *parser, yaml_event_t *event)
182	{
183	    assert(parser);     /* Non-NULL parser object is expected. */
184	    assert(event);      /* Non-NULL event object is expected. */
185	
186	    /* Erase the event object. */
187	
188	    memset(event, 0, sizeof(yaml_event_t));
189	
190	    /* No events after the end of the stream or error. */
191	
192	    if (parser->stream_end_produced || parser->error ||
193	            parser->state == YAML_PARSE_END_STATE) {
194	        return 1;
195	    }
196	
197	    /* Generate the next event. */
198	
199	    return yaml_parser_state_machine(parser, event);
200	}
201	
202	/*
203	 * Set parser error.
204	 */
205	
206	static int
207	yaml_parser_set_parser_error(yaml_parser_t *parser,
208	        const char *problem, yaml_mark_t problem_mark)
209	{
210	    parser->error = YAML_PARSER_ERROR;
211	    parser->problem = problem;
212	    parser->problem_mark = problem_mark;
213	
214	    return 0;
215	}
216	
217	static int
218	yaml_parser_set_parser_error_context(yaml_parser_t *parser,
219	        const char *context, yaml_mark_t context_mark,
220	        const char *problem, yaml_mark_t problem_mark)
221	{
222	    parser->error = YAML_PARSER_ERROR;
223	    parser->context = context;
224	    parser->context_mark = context_mark;
225	    parser->problem = problem;
226	    parser->problem_mark = problem_mark;
227	
228	    return 0;
229	}
