231	static int
232	yaml_maximum_level_reached(yaml_parser_t *parser,
233	        yaml_mark_t context_mark, yaml_mark_t problem_mark)
234	{
235	    yaml_parser_set_parser_error_context(parser,
236	            "while parsing", context_mark, "Maximum nesting level reached, set with yaml_set_max_nest_level())", problem_mark);
237	    return 0;
238	}
239	
240	/*
241	 * State dispatcher.
242	 */
243	
244	static int
245	yaml_parser_state_machine(yaml_parser_t *parser, yaml_event_t *event)
246	{
247	    switch (parser->state)
248	    {
249	        case YAML_PARSE_STREAM_START_STATE:
250	            return yaml_parser_parse_stream_start(parser, event);
251	
252	        case YAML_PARSE_IMPLICIT_DOCUMENT_START_STATE:
253	            return yaml_parser_parse_document_start(parser, event, 1);
254	
255	        case YAML_PARSE_DOCUMENT_START_STATE:
256	            return yaml_parser_parse_document_start(parser, event, 0);
257	
258	        case YAML_PARSE_DOCUMENT_CONTENT_STATE:
259	            return yaml_parser_parse_document_content(parser, event);
260	
261	        case YAML_PARSE_DOCUMENT_END_STATE:
262	            return yaml_parser_parse_document_end(parser, event);
263	
264	        case YAML_PARSE_BLOCK_NODE_STATE:
265	            return yaml_parser_parse_node(parser, event, 1, 0);
266	
267	        case YAML_PARSE_BLOCK_NODE_OR_INDENTLESS_SEQUENCE_STATE:
268	            return yaml_parser_parse_node(parser, event, 1, 1);
269	
270	        case YAML_PARSE_FLOW_NODE_STATE:
271	            return yaml_parser_parse_node(parser, event, 0, 0);
272	
273	        case YAML_PARSE_BLOCK_SEQUENCE_FIRST_ENTRY_STATE:
274	            return yaml_parser_parse_block_sequence_entry(parser, event, 1);
275	
276	        case YAML_PARSE_BLOCK_SEQUENCE_ENTRY_STATE:
277	            return yaml_parser_parse_block_sequence_entry(parser, event, 0);
278	
279	        case YAML_PARSE_INDENTLESS_SEQUENCE_ENTRY_STATE:
280	            return yaml_parser_parse_indentless_sequence_entry(parser, event);
281	
282	        case YAML_PARSE_BLOCK_MAPPING_FIRST_KEY_STATE:
283	            return yaml_parser_parse_block_mapping_key(parser, event, 1);
284	
285	        case YAML_PARSE_BLOCK_MAPPING_KEY_STATE:
286	            return yaml_parser_parse_block_mapping_key(parser, event, 0);
287	
288	        case YAML_PARSE_BLOCK_MAPPING_VALUE_STATE:
289	            return yaml_parser_parse_block_mapping_value(parser, event);
290	
291	        case YAML_PARSE_FLOW_SEQUENCE_FIRST_ENTRY_STATE:
292	            return yaml_parser_parse_flow_sequence_entry(parser, event, 1);
293	
294	        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_STATE:
295	            return yaml_parser_parse_flow_sequence_entry(parser, event, 0);
296	
297	        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_KEY_STATE:
298	            return yaml_parser_parse_flow_sequence_entry_mapping_key(parser, event);
299	
300	        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_VALUE_STATE:
301	            return yaml_parser_parse_flow_sequence_entry_mapping_value(parser, event);
302	
303	        case YAML_PARSE_FLOW_SEQUENCE_ENTRY_MAPPING_END_STATE:
304	            return yaml_parser_parse_flow_sequence_entry_mapping_end(parser, event);
305	
306	        case YAML_PARSE_FLOW_MAPPING_FIRST_KEY_STATE:
307	            return yaml_parser_parse_flow_mapping_key(parser, event, 1);
308	
309	        case YAML_PARSE_FLOW_MAPPING_KEY_STATE:
310	            return yaml_parser_parse_flow_mapping_key(parser, event, 0);
311	
312	        case YAML_PARSE_FLOW_MAPPING_VALUE_STATE:
313	            return yaml_parser_parse_flow_mapping_value(parser, event, 0);
314	
315	        case YAML_PARSE_FLOW_MAPPING_EMPTY_VALUE_STATE:
316	            return yaml_parser_parse_flow_mapping_value(parser, event, 1);
317	
318	        default:
319	            assert(1);      /* Invalid state. */
320	    }
321	
322	    return 0;
323	}
324	
325	/*
326	 * Parse the production:
327	 * stream   ::= STREAM-START implicit_document? explicit_document* STREAM-END
328	 *              ************
329	 */
330	
331	static int
332	yaml_parser_parse_stream_start(yaml_parser_t *parser, yaml_event_t *event)
333	{
334	    yaml_token_t *token;
335	
336	    token = PEEK_TOKEN(parser);
337	    if (!token) return 0;
338	
339	    if (token->type != YAML_STREAM_START_TOKEN) {
340	        return yaml_parser_set_parser_error(parser,
341	                "did not find expected <stream-start>", token->start_mark);
342	    }
343	
344	    parser->state = YAML_PARSE_IMPLICIT_DOCUMENT_START_STATE;
345	    STREAM_START_EVENT_INIT(*event, token->data.stream_start.encoding,
346	            token->start_mark, token->start_mark);
347	    SKIP_TOKEN(parser);
348	
349	    return 1;
350	}
351	
352	/*
353	 * Parse the productions:
354	 * implicit_document    ::= block_node DOCUMENT-END*
355	 *                          *
356	 * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
357	 *                          *************************
358	 */
359	
360	static int
361	yaml_parser_parse_document_start(yaml_parser_t *parser, yaml_event_t *event,
362	        int implicit)
363	{
364	    yaml_token_t *token;
365	    yaml_version_directive_t *version_directive = NULL;
366	    struct {
367	        yaml_tag_directive_t *start;
368	        yaml_tag_directive_t *end;
369	    } tag_directives = { NULL, NULL };
370	
371	    token = PEEK_TOKEN(parser);
372	    if (!token) return 0;
373	
374	    /* Parse extra document end indicators. */
375	
376	    if (!implicit)
377	    {
378	        while (token->type == YAML_DOCUMENT_END_TOKEN) {
379	            SKIP_TOKEN(parser);
380	            token = PEEK_TOKEN(parser);
381	            if (!token) return 0;
382	        }
383	    }
384	
385	    /* Parse an implicit document. */
386	
387	    if (implicit && token->type != YAML_VERSION_DIRECTIVE_TOKEN &&
388	            token->type != YAML_TAG_DIRECTIVE_TOKEN &&
389	            token->type != YAML_DOCUMENT_START_TOKEN &&
390	            token->type != YAML_STREAM_END_TOKEN)
391	    {
392	        if (!yaml_parser_process_directives(parser, NULL, NULL, NULL))
393	            return 0;
394	        if (!PUSH(parser, parser->states, YAML_PARSE_DOCUMENT_END_STATE))
395	            return 0;
396	        parser->state = YAML_PARSE_BLOCK_NODE_STATE;
397	        DOCUMENT_START_EVENT_INIT(*event, NULL, NULL, NULL, 1,
398	                token->start_mark, token->start_mark);
399	        return 1;
400	    }
401	
402	    /* Parse an explicit document. */
403	
404	    else if (token->type != YAML_STREAM_END_TOKEN)
405	    {
406	        yaml_mark_t start_mark, end_mark;
407	        start_mark = token->start_mark;
408	        if (!yaml_parser_process_directives(parser, &version_directive,
409	                    &tag_directives.start, &tag_directives.end))
410	            return 0;
411	        token = PEEK_TOKEN(parser);
412	        if (!token) goto error;
413	        if (token->type != YAML_DOCUMENT_START_TOKEN) {
414	            yaml_parser_set_parser_error(parser,
415	                    "did not find expected <document start>", token->start_mark);
416	            goto error;
417	        }
418	        if (!PUSH(parser, parser->states, YAML_PARSE_DOCUMENT_END_STATE))
419	            goto error;
420	        parser->state = YAML_PARSE_DOCUMENT_CONTENT_STATE;
421	        end_mark = token->end_mark;
422	        DOCUMENT_START_EVENT_INIT(*event, version_directive,
423	                tag_directives.start, tag_directives.end, 0,
424	                start_mark, end_mark);
425	        SKIP_TOKEN(parser);
426	        version_directive = NULL;
427	        tag_directives.start = tag_directives.end = NULL;
428	        return 1;
429	    }
430	
431	    /* Parse the stream end. */
432	
433	    else
434	    {
435	        parser->state = YAML_PARSE_END_STATE;
436	        STREAM_END_EVENT_INIT(*event, token->start_mark, token->end_mark);
437	        SKIP_TOKEN(parser);
438	        return 1;
439	    }
440	
441	error:
442	    yaml_free(version_directive);
443	    while (tag_directives.start != tag_directives.end) {
444	        yaml_free(tag_directives.end[-1].handle);
445	        yaml_free(tag_directives.end[-1].prefix);
446	        tag_directives.end --;
447	    }
448	    yaml_free(tag_directives.start);
449	    return 0;
450	}
451	
452	/*
453	 * Parse the productions:
454	 * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
455	 *                                                    ***********
456	 */
457	
458	static int
459	yaml_parser_parse_document_content(yaml_parser_t *parser, yaml_event_t *event)
460	{
461	    yaml_token_t *token;
462	
463	    token = PEEK_TOKEN(parser);
464	    if (!token) return 0;
465	
466	    if (token->type == YAML_VERSION_DIRECTIVE_TOKEN ||
467	            token->type == YAML_TAG_DIRECTIVE_TOKEN ||
468	            token->type == YAML_DOCUMENT_START_TOKEN ||
469	            token->type == YAML_DOCUMENT_END_TOKEN ||
470	            token->type == YAML_STREAM_END_TOKEN) {
471	        parser->state = POP(parser, parser->states);
472	        return yaml_parser_process_empty_scalar(parser, event,
473	                token->start_mark);
474	    }
475	    else {
476	        return yaml_parser_parse_node(parser, event, 1, 0);
477	    }
478	}
479	
480	/*
481	 * Parse the productions:
482	 * implicit_document    ::= block_node DOCUMENT-END*
483	 *                                     *************
484	 * explicit_document    ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
485	 *                                                                *************
486	 */
487	
488	static int
489	yaml_parser_parse_document_end(yaml_parser_t *parser, yaml_event_t *event)
490	{
491	    yaml_token_t *token;
492	    yaml_mark_t start_mark, end_mark;
493	    int implicit = 1;
494	
495	    token = PEEK_TOKEN(parser);
496	    if (!token) return 0;
497	
498	    start_mark = end_mark = token->start_mark;
499	
500	    if (token->type == YAML_DOCUMENT_END_TOKEN) {
501	        end_mark = token->end_mark;
502	        SKIP_TOKEN(parser);
503	        implicit = 0;
504	    }
505	
506	    while (!STACK_EMPTY(parser, parser->tag_directives)) {
507	        yaml_tag_directive_t tag_directive = POP(parser, parser->tag_directives);
508	        yaml_free(tag_directive.handle);
509	        yaml_free(tag_directive.prefix);
510	    }
511	
512	    parser->state = YAML_PARSE_DOCUMENT_START_STATE;
513	    DOCUMENT_END_EVENT_INIT(*event, implicit, start_mark, end_mark);
514	
515	    return 1;
516	}
517	
518	/*
519	 * Parse the productions:
520	 * block_node_or_indentless_sequence    ::=
521	 *                          ALIAS
522	 *                          *****
523	 *                          | properties (block_content | indentless_block_sequence)?
524	 *                            **********  *
525	 *                          | block_content | indentless_block_sequence
526	 *                            *
527	 * block_node           ::= ALIAS
528	 *                          *****
529	 *                          | properties block_content?
530	 *                            ********** *
531	 *                          | block_content
532	 *                            *
533	 * flow_node            ::= ALIAS
534	 *                          *****
535	 *                          | properties flow_content?
536	 *                            ********** *
537	 *                          | flow_content
538	 *                            *
539	 * properties           ::= TAG ANCHOR? | ANCHOR TAG?
540	 *                          *************************
541	 * block_content        ::= block_collection | flow_collection | SCALAR
542	 *                                                               ******
543	 * flow_content         ::= flow_collection | SCALAR
544	 *                                            ******
545	 */
546	
547	static int
548	yaml_parser_parse_node(yaml_parser_t *parser, yaml_event_t *event,
549	        int block, int indentless_sequence)
550	{
551	    yaml_token_t *token;
552	    yaml_char_t *anchor = NULL;
553	    yaml_char_t *tag_handle = NULL;
554	    yaml_char_t *tag_suffix = NULL;
555	    yaml_char_t *tag = NULL;
556	    yaml_mark_t start_mark, end_mark, tag_mark;
557	    int implicit;
558	
559	    token = PEEK_TOKEN(parser);
560	    if (!token) return 0;
561	
562	    if (token->type == YAML_ALIAS_TOKEN)
563	    {
564	        parser->state = POP(parser, parser->states);
565	        ALIAS_EVENT_INIT(*event, token->data.alias.value,
566	                token->start_mark, token->end_mark);
567	        SKIP_TOKEN(parser);
568	        return 1;
569	    }
570	
571	    else
572	    {
573	        start_mark = end_mark = token->start_mark;
574	
575	        if (token->type == YAML_ANCHOR_TOKEN)
576	        {
577	            anchor = token->data.anchor.value;
578	            start_mark = token->start_mark;
579	            end_mark = token->end_mark;
580	            SKIP_TOKEN(parser);
581	            token = PEEK_TOKEN(parser);
582	            if (!token) goto error;
583	            if (token->type == YAML_TAG_TOKEN)
584	            {
585	                tag_handle = token->data.tag.handle;
586	                tag_suffix = token->data.tag.suffix;
587	                tag_mark = token->start_mark;
588	                end_mark = token->end_mark;
589	                SKIP_TOKEN(parser);
590	                token = PEEK_TOKEN(parser);
591	                if (!token) goto error;
592	            }
593	        }
594	        else if (token->type == YAML_TAG_TOKEN)
595	        {
596	            tag_handle = token->data.tag.handle;
597	            tag_suffix = token->data.tag.suffix;
598	            start_mark = tag_mark = token->start_mark;
599	            end_mark = token->end_mark;

