279	YAML_DECLARE(int)
280	yaml_emitter_emit(yaml_emitter_t *emitter, yaml_event_t *event)
281	{
282	    if (!ENQUEUE(emitter, emitter->events, *event)) {
283	        yaml_event_delete(event);
284	        return 0;
285	    }
286	
287	    while (!yaml_emitter_need_more_events(emitter)) {
288	        if (!yaml_emitter_analyze_event(emitter, emitter->events.head))
289	            return 0;
290	        if (!yaml_emitter_state_machine(emitter, emitter->events.head))
291	            return 0;
292	        yaml_event_delete(&DEQUEUE(emitter, emitter->events));
293	    }
294	
295	    return 1;
296	}
