298	/*
299	 * Check if we need to accumulate more events before emitting.
300	 *
301	 * We accumulate extra
302	 *  - 1 event for DOCUMENT-START
303	 *  - 2 events for SEQUENCE-START
304	 *  - 3 events for MAPPING-START
305	 */
306	
307	static int
308	yaml_emitter_need_more_events(yaml_emitter_t *emitter)
309	{
310	    int level = 0;
311	    int accumulate = 0;
312	    yaml_event_t *event;
313	
314	    if (QUEUE_EMPTY(emitter, emitter->events))
315	        return 1;
316	
317	    switch (emitter->events.head->type) {
318	        case YAML_DOCUMENT_START_EVENT:
319	            accumulate = 1;
320	            break;
321	        case YAML_SEQUENCE_START_EVENT:
322	            accumulate = 2;
323	            break;
324	        case YAML_MAPPING_START_EVENT:
325	            accumulate = 3;
326	            break;
327	        default:
328	            return 0;
329	    }
330	
331	    if (emitter->events.tail - emitter->events.head > accumulate)
332	        return 0;
333	
334	    for (event = emitter->events.head; event != emitter->events.tail; event ++) {
335	        switch (event->type) {
336	            case YAML_STREAM_START_EVENT:
337	            case YAML_DOCUMENT_START_EVENT:
338	            case YAML_SEQUENCE_START_EVENT:
339	            case YAML_MAPPING_START_EVENT:
340	                level += 1;
341	                break;
342	            case YAML_STREAM_END_EVENT:
343	            case YAML_DOCUMENT_END_EVENT:
344	            case YAML_SEQUENCE_END_EVENT:
345	            case YAML_MAPPING_END_EVENT:
346	                level -= 1;
347	                break;
348	            default:
349	                break;
350	        }
351	        if (!level)
352	            return 0;
353	    }
354	
355	    return 1;
356	}
