364	        yaml_tag_directive_t value, int allow_duplicates)
365	{
366	    yaml_tag_directive_t *tag_directive;
367	    yaml_tag_directive_t copy = { NULL, NULL };
368	
369	    for (tag_directive = emitter->tag_directives.start;
370	            tag_directive != emitter->tag_directives.top; tag_directive ++) {
371	        if (strcmp((char *)value.handle, (char *)tag_directive->handle) == 0) {
372	            if (allow_duplicates)
373	                return 1;
374	            return yaml_emitter_set_emitter_error(emitter,
375	                    "duplicate %TAG directive");
376	        }
377	    }
378	
379	    copy.handle = yaml_strdup(value.handle);
380	    copy.prefix = yaml_strdup(value.prefix);
381	    if (!copy.handle || !copy.prefix) {
382	        emitter->error = YAML_MEMORY_ERROR;
383	        goto error;
384	    }
385	
386	    if (!PUSH(emitter, emitter->tag_directives, copy))
387	        goto error;
388	
389	    return 1;
390	
