435	
436	        case YAML_EMIT_DOCUMENT_CONTENT_STATE:
437	            return yaml_emitter_emit_document_content(emitter, event);
438	
439	        case YAML_EMIT_DOCUMENT_END_STATE:
440	            return yaml_emitter_emit_document_end(emitter, event);
441	
442	        case YAML_EMIT_FLOW_SEQUENCE_FIRST_ITEM_STATE:
443	            return yaml_emitter_emit_flow_sequence_item(emitter, event, 1);
444	
445	        case YAML_EMIT_FLOW_SEQUENCE_ITEM_STATE:
446	            return yaml_emitter_emit_flow_sequence_item(emitter, event, 0);
447	
448	        case YAML_EMIT_FLOW_MAPPING_FIRST_KEY_STATE:
449	            return yaml_emitter_emit_flow_mapping_key(emitter, event, 1);
450	
451	        case YAML_EMIT_FLOW_MAPPING_KEY_STATE:
452	            return yaml_emitter_emit_flow_mapping_key(emitter, event, 0);
453	
454	        case YAML_EMIT_FLOW_MAPPING_SIMPLE_VALUE_STATE:
455	            return yaml_emitter_emit_flow_mapping_value(emitter, event, 1);
456	
457	        case YAML_EMIT_FLOW_MAPPING_VALUE_STATE:
458	            return yaml_emitter_emit_flow_mapping_value(emitter, event, 0);
459	
460	        case YAML_EMIT_BLOCK_SEQUENCE_FIRST_ITEM_STATE:
461	            return yaml_emitter_emit_block_sequence_item(emitter, event, 1);
462	
463	        case YAML_EMIT_BLOCK_SEQUENCE_ITEM_STATE:
464	            return yaml_emitter_emit_block_sequence_item(emitter, event, 0);
465	
466	        case YAML_EMIT_BLOCK_MAPPING_FIRST_KEY_STATE:
467	            return yaml_emitter_emit_block_mapping_key(emitter, event, 1);
468	
469	        case YAML_EMIT_BLOCK_MAPPING_KEY_STATE:
470	            return yaml_emitter_emit_block_mapping_key(emitter, event, 0);
471	
472	        case YAML_EMIT_BLOCK_MAPPING_SIMPLE_VALUE_STATE:
473	            return yaml_emitter_emit_block_mapping_value(emitter, event, 1);
474	
475	        case YAML_EMIT_BLOCK_MAPPING_VALUE_STATE:
476	            return yaml_emitter_emit_block_mapping_value(emitter, event, 0);
477	
478	        case YAML_EMIT_END_STATE:
