        if PUSH!(context_ptr, (*document).nodes, node) == 0 {
            break 'error 0;
        }

        ((*document).nodes.top.offset_from((*document).nodes.start)) as c_int
    };

    if ok == 0 {
        yaml_free(tag_copy as *mut c_void);
        yaml_free(value_copy as *mut c_void);
        return 0;
    }

    ok
}

