}

macro_rules! MAPPING_START_EVENT_INIT {
    ($event:expr, $anchor:expr, $tag:expr, $implicit:expr, $style:expr, $start_mark:expr, $end_mark:expr) => {
        EVENT_INIT!($event, YAML_MAPPING_START_EVENT, $start_mark, $end_mark);
