macro_rules! STREAM_START_EVENT_INIT {
    ($event:expr, $encoding:expr, $start_mark:expr, $end_mark:expr) => {
        EVENT_INIT!($event, YAML_STREAM_START_EVENT, $start_mark, $end_mark);
        $event.data.stream_start.encoding = $encoding;
    };
}

