            if tag_copy.is_null() {
                break 'error 0;
            }
        }

        MAPPING_START_EVENT_INIT!(*event, anchor_copy, tag_copy, implicit, style, mark, mark);
        1i32
    };

    if ok == 0 {
        yaml_free(anchor_copy as *mut c_void);
        yaml_free(tag_copy as *mut c_void);
        return 0;
    }

    1
}

